mapper.select:
SELECT id, user_exploration_id, memo, place_name, checked_at, created_at, updated_at FROM (
    SELECT w.*, ROW_NUMBER() OVER (PARTITION BY w.user_exploration_id ORDER BY w.checked_at DESC, w.id DESC) AS rn
    FROM waypoints w
    WHERE w.user_exploration_id IN

        #{id}

) t WHERE t.rn = 1
